#!/usr/bin/env python3
"""protein/thermompnn_stability — auto-generated run.py (archetype=mutation_scan).

第一版只实现 simulate 模式:从 stdin/args 拿 inputs,产合理合成数据 JSON。
真实现路径(simulate=False)留 stub:返回 not-implemented + 提示。

输入契约:
  stdin JSON,字段按 SKILL.md 的 inputs 段;simulate 默认 true。
  CLI 兜底:--simulate / 各位置参数。

输出:
  stdout JSON;失败时也写 JSON {"ok": false, "error": "..."} 而非裸 traceback。
"""
import json
import sys

ARCHETYPE = "mutation_scan"
BRAIN = "protein"
SKILL = "thermompnn_stability"

def simulate(payload):
    """auto-generated by regen_simulate.py — outputs schema 来自 SKILL.md."""
    import copy
    import random
    random.seed(int(payload.get("seed", 42)) if isinstance(payload, dict) else 42)
    out = copy.deepcopy({'skill_id': 'thermompnn_stability', 'wt_score': 0.0, 'scan_csv': '', 'top_mutations': [{'position': 1, 'from_aa': 'A', 'to_aa': 'V', 'ddg': 0.0}], 'diagnostics': {'brain': 'protein', 'archetype': 'mutation_scan'}})
    if isinstance(out, dict):
        out.setdefault("diagnostics", {})
        if isinstance(out["diagnostics"], dict):
            out["diagnostics"].update({
                "simulated": True,
                "archetype": ARCHETYPE,
                "brain": BRAIN,
                "skill": SKILL,
            })
        if "skill_id" in out and not out["skill_id"]:
            out["skill_id"] = SKILL
    return out

def real(payload):
    """ThermoMPNN 单点突变 ΔΔG 预测(site saturation mutagenesis)。
    入口 analysis/custom_inference.py CLI(--pdb/--chain/--out_dir);
    host_env=thermompnn,产出 ThermoMPNN_inference_*.csv 的 ddG_pred 列。
    """
    import os as _os
    import tempfile as _tempfile
    import time as _time
    try:
        from brains._common.lib.run_tool import run_tool
    except ImportError:
        import sys as _sys
        _sys.path.insert(0, "/home/zkyd/data1/mzy/praxis2-brains")
        from _common.lib.run_tool import run_tool  # noqa: F401
    pdb = payload.get("input_pdb") or payload.get("structure_pdb")
    out_dir = payload.get("out_dir") or _tempfile.mkdtemp(prefix="thermompnn_")
    diagnostics = {"brain": BRAIN, "skill": SKILL, "archetype": ARCHETYPE,
                   "tool": "ThermoMPNN", "out_dir": out_dir}
    if _os.environ.get("PRAXIS_SKILL_DRY_HOST") == "1":
        return {"ok": True, "skill_id": SKILL, "wt_score": 0.0, "scan_csv": "",
                "top_mutations": [], "diagnostics": {**diagnostics, "dry": True}}
    if not pdb or not _os.path.isfile(pdb):
        return {"ok": False, "error": f"input_pdb 不存在", "diagnostics": diagnostics}
    # ThermoMPNN 真实入口:analysis/custom_inference.py(site saturation mutagenesis CLI)。
    # 产出 out_dir/ThermoMPNN_inference_<stem>.csv(列 ddG_pred/position/wildtype/mutation)。
    # host_env=thermompnn(SKILL.md frontmatter);须在 analysis/ 下跑(仓库相对 import)。
    chain = payload.get("chain", "A")
    repo = "/home/zkyd/data2/mzy/binaries/ThermoMPNN"
    _os.makedirs(out_dir, exist_ok=True)
    cmd = ["python", f"{repo}/analysis/custom_inference.py",
           "--pdb", pdb, "--chain", chain, "--out_dir", out_dir]
    t0 = _time.time()
    r = run_tool(cmd, cwd=f"{repo}/analysis", timeout=int(payload.get("timeout_s", 600)))
    diagnostics["subprocess"] = {"wall_sec": r.get("wall_sec"), "rc": r.get("returncode")}
    if not r["ok"]:
        return {"ok": False, "error": r.get("error", "ThermoMPNN custom_inference 失败"),
                "stderr": r.get("stderr", "")[-400:], "diagnostics": diagnostics}
    import csv as _csv
    import glob as _glob
    csvs = _glob.glob(_os.path.join(out_dir, "ThermoMPNN_inference_*.csv"))
    if not csvs:
        return {"ok": False, "error": "未找到 ThermoMPNN 输出 CSV",
                "stderr": r.get("stdout", "")[-300:], "diagnostics": diagnostics}
    scan_csv = csvs[0]

    def _ddg(x):
        try:
            return float(x.get("ddG_pred", 0.0))
        except (ValueError, TypeError):
            return 0.0
    rows = sorted(_csv.DictReader(open(scan_csv, encoding="utf-8")), key=_ddg)
    top = [{"position": int(float(x.get("position", 0) or 0)),
            "from_aa": x.get("wildtype", ""), "to_aa": x.get("mutation", ""),
            "ddg": _ddg(x)} for x in rows[:10]]
    return {"ok": True, "skill_id": SKILL, "wt_score": 0.0,
            "scan_csv": scan_csv, "top_mutations": top,
            "runtime_sec": round(_time.time() - t0, 2), "diagnostics": diagnostics}

def main():
    # stdin 优先(SkillExecTool 走 stdin)
    payload = {}
    if not sys.stdin.isatty():
        try:
            payload = json.load(sys.stdin)
            if not isinstance(payload, dict):
                payload = {}
        except json.JSONDecodeError:
            payload = {}
    if not payload:
        # 简易 CLI 兜底
        import argparse
        ap = argparse.ArgumentParser()
        ap.add_argument("--simulate", action="store_true", default=True)
        ap.add_argument("--seed", type=int, default=42)
        args, _ = ap.parse_known_args()
        payload = {"simulate": args.simulate, "seed": args.seed}

    simulate_mode = bool(payload.get("simulate", True))
    try:
        out = simulate(payload) if simulate_mode else real(payload)
    except Exception as e:
        out = {"ok": False, "error": f"run.py 内部错误: {e!r}"}

    if isinstance(out, dict):
        out.setdefault("diagnostics", {})
        if isinstance(out["diagnostics"], dict):
            out["diagnostics"].update({"archetype": ARCHETYPE, "brain": BRAIN, "skill": SKILL})
    json.dump(out, sys.stdout, ensure_ascii=False)
    sys.stdout.write("\n")
    return 0

if __name__ == "__main__":
    sys.exit(main())
